import os
import boto3
from typing import Dict, Any

def get_aws_client(service_name: str, region_name: str = None):
    """Provides a configured AWS client for a given service."""
    aws_access_key_id = os.environ.get("AWS_ACCESS_KEY_ID")
    aws_secret_access_key = os.environ.get("AWS_SECRET_ACCESS_KEY")
    aws_region = region_name or os.environ.get("AWS_REGION", "us-east-1")

    if aws_access_key_id and aws_secret_access_key:
        return boto3.client(
            service_name,
            region_name=aws_region,
            aws_access_key_id=aws_access_key_id,
            aws_secret_access_key=aws_secret_access_key
        )
    else:
        # Fallback to default AWS credential chain (e.g., IAM roles, ~/.aws/credentials)
        return boto3.client(service_name, region_name=aws_region)


def load_config() -> Dict[str, Any]:
    """Loads configuration from environment variables or a default.
    For a real application, this would load from a more robust config management system.
    """
    return {
        "aws_region": os.environ.get("AWS_REGION", "us-east-1"),
        "textract_feature_types": ["FORMS", "TABLES"], # Example feature types
    }

import boto3
from typing import Dict, Any, List
from document_models import DocumentExtractionRequest, ReceiptFields, LineItem
from document_client import get_aws_client

def extract_receipt_fields(request: DocumentExtractionRequest, config: Dict[str, Any] = None) -> Dict[str, Any]:
    config = config or {}
    textract_client = get_aws_client("textract", region_name=config.get("aws_region"))

    response = textract_client.analyze_expense(Document={"Bytes": request.document_bytes})

    receipts = []
    for document in response["ExpenseDocuments"]:
        fields = {f["Type"]["Text"]: f["ValueDetection"].get("Text", "") for f in document["SummaryFields"]}
        items: List[LineItem] = []
        for group in document.get("LineItemGroups", []):
            for item_data in group["LineItems"]:
                values = {f["Type"]["Text"]: f["ValueDetection"].get("Text", "") for f in item_data["LineItemExpenseFields"]}
                items.append(LineItem(description=values.get("ITEM"), quantity=values.get("QUANTITY"), amount=values.get("PRICE")))

        receipts.append(ReceiptFields(
            merchant=fields.get("MERCHANT_NAME"),
            tax=fields.get("TOTAL_TAX"),
            total=fields.get("TOTAL"),
            items=items
        ).dict())

    return {"receipts": receipts}

import os
from typing import Dict, Any
from document_models import InvoiceFields
import google.generativeai as genai

def summarize_invoice_fields(invoice_fields: InvoiceFields) -> Dict[str, Any]:
    # Configure the Generative AI client
    genai.configure(api_key=os.environ.get("GOOGLE_API_KEY"))
    model = genai.GenerativeModel('gemini-pro')

    summary_prompt = f"""Summarize the following invoice details in a concise paragraph:
    Vendor: {invoice_fields.vendor}
    Date: {invoice_fields.date}
    Total: {invoice_fields.total}
    Line Items: {', '.join([f'{item.description} (Qty: {item.quantity}, Amt: {item.amount})' for item in invoice_fields.line_items])}
    """

    try:
        response = model.generate_content(summary_prompt)
        summary_text = response.text
    except Exception as e:
        summary_text = f"Failed to generate summary: {e}"

    return {"invoice_summary": summary_text}

import os
from typing import Dict, Any, List
from google.cloud import translate_v2 as translate

def translate_invoice_notes(notes: List[str], target_language: str = "en") -> Dict[str, Any]:
    # Set up Google Cloud Translation client
    # Ensure GOOGLE_APPLICATION_CREDENTIALS environment variable is set or configure authentication
    translate_client = translate.Client()

    translated_notes: List[str] = []
    for note in notes:
        try:
            result = translate_client.translate(note, target_language=target_language)
            translated_notes.append(result["translatedText"])
        except Exception as e:
            translated_notes.append(f"Translation failed for '{note}': {e}")

    return {"original_notes": notes, "translated_notes": translated_notes, "target_language": target_language}

import os
