from typing import Dict, Any
from document_models import NormalizedExpense
from document_client import get_aws_client

def persist_expense_record(expense_record: NormalizedExpense, document_id: str) -> Dict[str, Any]:
    dynamodb_client = get_aws_client("dynamodb", region_name=os.environ.get("AWS_REGION"))
    table_name = os.environ.get("EXPENSE_RECORDS_TABLE_NAME", "ExpenseRecords")

    # Convert NormalizedExpense to a dictionary suitable for DynamoDB
    # DynamoDB requires attribute values to be typed (e.g., S for string, N for number)
    # For simplicity, we'll convert the Pydantic model to a dict, and boto3 will handle basic types.
    # For more complex types like lists of dicts, explicit serialization might be needed.
    item = expense_record.dict()
    item["document_id"] = document_id # Add document_id as primary key

    try:
        response = dynamodb_client.put_item(
            TableName=table_name,
            Item={
                k: {"S": str(v)} if isinstance(v, str) else 
                     {"N": str(v)} if isinstance(v, (int, float)) else 
                     {"M": {k_inner: {"S": str(v_inner)} for k_inner, v_inner in v.items()}} if isinstance(v, dict) else
                     {"L": [{\
"S": str(item_inner)} for item_inner in v]} if isinstance(v, list) and all(isinstance(item_inner, (str, int, float)) for item_inner in v) else # Simplified list handling
                     {"S": json.dumps(v)} # Fallback for complex types, needs import json
                for k, v in item.items()
            }
        )
        return {"status": "success", "document_id": document_id, "response": response}
    except Exception as e:
        return {"status": "error", "document_id": document_id, "message": f"Failed to persist record: {e}"}
